import{_ as B,H as e,f as t,i as A}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"第二十一封信-“要么横着涂，要么竖着涂”（下）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第二十一封信-“要么横着涂，要么竖着涂”（下）.md","filePath":"去无方向的信/第二十一封信-“要么横着涂，要么竖着涂”（下）.md","lastUpdated":1795542896000}'),i={name:"去无方向的信/第二十一封信-“要么横着涂，要么竖着涂”（下）.md"};function a(s,E,n,p,o,C){return e(),t("div",null,[...E[0]||(E[0]=[A('<h1 id="第二十一封信-要么横着涂-要么竖着涂-下" tabindex="-1">第二十一封信-“要么横着涂，要么竖着涂”（下） <a class="header-anchor" href="#第二十一封信-要么横着涂-要么竖着涂-下" aria-label="Permalink to &quot;第二十一封信-“要么横着涂，要么竖着涂”（下）&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/3.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/4.png" alt=""></a></p><ul><li><p>历史小知识</p></li><li><p>“在 1960 到 1973 年间，徕兹公司 (LEITZ) 为自动对焦和相应的传感器阵列技术申请了一系列专利；在 1976 年的 &#39;photokina &#39;大会上，徕兹展出了基于之前技术开发的产品&#39;Correfot &#39;；1978 年，他们又展示了一台具备完全可用的自动对焦系统的单反相机，而其后进展甚缓。</p></li><li><p>世界上第一台量产的自动对焦民用相机或许可追溯到 ‘ 柯尼卡 (Konica) C35 AF ’ —— 于1977 年发布的一台便携式 P&amp;S 机 (Point &amp; Shoot)……而随后于 1978 年发布的 宝丽来(Polaroid) SX-70 则是第一台量产的拥有自动对焦功能的单反相机。</p></li><li><p>1981 年宾得 (Pentax) 推出的 ME-F 是一台使用机内传感器与带镜头马达的 35mm 规格的自动对焦单反相机；稍后在 1983 年，由 尼康 (Nikon) 推出了 F3 AF，这是他们的第一台自动对焦相机，设计原理跟 ME-F 差不多；时间到了 1985 年，美能达 (Minolta) 发布了第一套完整的可换镜头的自动对焦单反系统 —— Minolta AF，以 Minolta 7000 为代表，可以推动相关的 Minolta AF 镜头群实现自动对焦；紧随其后，尼康和宾得推出了自己的自动对焦系统，同时保持了对于之前系统镜头的兼容性；而更迟一些，在 1987 年发布的 佳能(Canon) EOS 系统让镜头配置马达以控制光圈与自动对焦，机身则仅传递电子信号。” —— 摘自 Wikipedia</p></li><li><p>• Henri Cartier-Bresson 在 1952 年出版了Images à la Sauvette（《决定性瞬间》）。• 森山大道在 1967 年获得了日本摄影评论家协会新人奖。• Josef Koudelka 在 1968 年拍摄了苏联入侵布拉格 (Invasion 68: Prague)。• 石内都在 1969 年获得了木村伊兵卫摄影奖。• 东松照明在 1975 年出版了《太阳の铅笔》。• Nan Goldin 在 1986 年出版了 The Ballad of Sexual Dependency。• Alex Webb 2011 年出版的 The Suffering of Light 的副标题是 &quot; Thirty Years ofPhotographs &quot;，三十年精选……这本儿画册的封面照片儿是 1981 年拍摄的。• 被雪藏了五六十年的 Saul Leiter，于 2013 年 11 月 26 日在纽约去世。</p></li><li><p>……</p></li><li><p>这所有的荣光</p></li><li><p>都与自动对焦无关</p></li></ul><p>生生：</p><p>你好哇。</p><p>前面几封信让你看了不少照片儿，他们都非常好看，他们都不太像我们平常拍的照片儿，他们一看就是那种“大师照片儿”。但我们现在已经比较清楚他们的小伎俩了，至少在技术上已经基本不再神秘了。</p><p>他们用阳光十六法则应付室外，他们用阳光十六衍生法则应付室内或暗光环境，牢牢地把住了曝光；他们都有自己非常惯用的镜头，他们非常熟悉自己的镜头焦段的“框”，牢牢地把住了画面取景范围；他们都有一个自己觉得非常舒服的距离，有人选择远远地拍，他就一辈子远远的，有人选择把相机㨃到人脸上拍，他就一辈子㨃人脸。</p><p>之前我跟你说过，在绝大多数日常拍摄的情况下，我们只有把相机里所有默认开启的“自动功能”都给关上，才有可能真的拍到一些什么。聊到现在，我们已经基本把所有要靠自己搞定的东西都揽回到我们自己手里了，最后只剩下一个大问题还没有解决，一个非常大的麻烦——对焦。</p><p>我们绝大多数人常用自动对焦，然后基本上拍出来的照片儿就是咱们照片儿的那个样儿，但那些摄影大师呢？他们基本都不用自动对焦，或者这么说吧，他们好多人想用都用不了，因为当时没有，他们在没有自动对焦干扰的情况下，拍出来的照片儿就是他们照片儿的那个样儿。所以，这会不会侧面地说明了这么一个事儿：对焦方式会影响照片儿的样子？</p><p>我从第十二封信开始铺垫，铺垫到现在，中间聊了那么多那么多，聊定焦镜头，聊变焦镜头，聊距离，聊框，聊“要么横着涂，要么竖着涂”……这一切，都是为了今天，因为自动对焦太要命了，你要摆脱它，越早越好，越快越好。</p><p>我先给你看看“自动对焦”的遗毒。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/5.jpeg" alt=""></a></p><p>如果你用自动对焦，相机默认会把对焦点放在画面正中心，即便你可以调整对焦点的位置，但基本所有人都会觉得很麻烦，而且，如果拍完一张照片儿，你忘了把对焦点调回到中心，等拍下一张照片儿的时候就容易对焦在不对的地方儿。所以，绝大多数情况下，我们都倾向于把对焦点固定放在画面中心。</p><p>自动对焦还有一个特点，它会诱惑你死死地盯着那个对焦点，盯到你眼里只有那个绿色的对焦框，又因为这个绿色的对焦框经常在画面中心，所以慢慢儿地，你会发现，你每一张照片儿的主体都在画面中心，而且除了这个主体之外，再也没有什么别的东西可看了。因为你拍的时候只能看到那个主体，其实也不是因为你只能看见那个主体，而是因为你只能看见那个绿色的对焦框。</p><p>上面两张照片儿都不是用自动对焦拍的，但看起来都特别像用自动对焦拍的，为什么？就是因为我之前不会拍照片儿的时候用自动对焦中毒太深了，现在解毒的过程就很费劲。</p><p>想要解决这个问题并没有你想象的那么简单，你可能以为有很多种解决方案：比如自动对焦二次构图，先对焦，然后让镜头往左往右或往上往下偏一点儿；比如，反正我现在不用自动对焦，那就强行不把主体放在中间不就行了么，又不是做不到；比如，实在不行就靠后期裁切，把主体放在什么三分点上。</p><p>如果你这么想，说明你还没有意识到一个问题，那就是：视觉习惯。</p><p>我知道单一主体很无聊，我知道把主体放在中间很无聊，我知道我现在不用自动对焦我很自由，想把主体放在哪儿就放在哪儿，但因为之前用自动对焦拍了太久，我现在前期拍摄的时候，只有主体在中间我看着才舒服。</p><p>再次强调，即便我非常清楚这样很无聊，但就是很难克服这个视觉习惯。</p><p>之前的那些摄影师，他们从最一开始就是旁轴取景手动对焦，他们的画面感是取景框里的一切，而不是对焦框，所以他们很难会觉得主体只有放在中间才最舒服——天生吃有机蔬菜的不会知道农药什么味儿。</p><p>对焦方式会影响我们看世界的维度，左右我们看世界的角度，而我们看世界的维度和角度会直接反映在我们拍的照片儿上……所以，依赖自动对焦的我们，拍出来的照片儿才都那么平庸。</p><p>看 Gueorgui Pinkhassov 拍的大鸡。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/6.png" alt=""></a></p><p>我很确定他没用自动对焦，因为我知道他拍这张照片儿的时候用的是一台 Leica M 系旁轴相机，所以他只拍一只鸡都可以把画面拍得这么复杂，精巧且简洁的复杂。</p><p>你可能会奇怪，这只大白鸡和这张看起来干干净净的照片儿有什么好复杂的？首先，如果是你，你能不能看到这只被一小束阳光打亮鸡头的鸡？其次，你能不能观察到用白色的墙当背景可以凸显出黑色的人影，然后用黑色的人影当背景又可以凸显出这只大白鸡？最后，也是最重要的，你能不能一抬手儿就抓到这个瞬间？</p><p>Gueorgui Pinkhassov 有一篇专访，专门儿讲这张照片儿，他说他当时就直觉性地拍了三张，没考虑太多，上面那张成片儿是第一张，第二张大鸡闭眼了，第三张鸡头动了一点点，动进了阴影中，然后他就没有再继续拍了。事实上，他在很多专访里都有谈到这张照片儿，因为这只鸡是摄影界的名鸡，这只鸡就像寇老师的那条狗一样，是 &quot; The Rooster（那只鸡）&quot;，不是 arooster（一只鸡）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B8%2580%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E8%25A6%2581%25E4%25B9%2588%25E6%25A8%25AA%25E7%259D%2580%25E6%25B6%2582%25EF%25BC%258C%25E8%25A6%2581%25E4%25B9%2588%25E7%25AB%2596%25E7%259D%2580%25E6%25B6%2582%25E2%2580%259D%25EF%25BC%2588%25E4%25B8%258B%25EF%25BC%2589/7.png" alt=""></a></p><ul><li>Josef Koudelka</li></ul><p>他当时直觉性地拍了三张？他的直觉怎么那么好？这个咱们后面会说到，而现在我们最需要关注的是他“一抬手儿就拍了”。</p><p>一抬手儿就拍的话，又没有自动对焦，那他是怎么对上焦的呢？先不说他的相机本身就没有自动对焦的功能，关键是，即便有也显然不行，来不及嘛……但手动对焦更不行，因为在这种情况下，手动对焦一定比自动对焦还要慢，他可是一抬手儿就拍了，拍了三张，最后只有第一张成图了，也就是说，如果没赶上第一张的那个时机，稍微慢一点儿就变成第二三张废片了。</p><p>所以他是怎么抓拍到这个一闪而过的瞬间的呢？答案就是：不对焦，因为再快的自动对焦和手动对焦也没有不对焦快。</p><p>咱们下次开始正经聊这事儿，让你一抬手儿就能按下去快门，让你不对焦也能对上焦。</p><p>P.S. 多说一句，我现在只要看见大鸡就会拍照片儿，希望你已经知道我为什么会这样了，哈！！！</p>',36)])])}const g=B(i,[["render",a]]);export{l as __pageData,g as default};
